<span class="line">    <span class="token keyword">virtual</span> <span class="token keyword">void</span> <span class="token function">setCallbacks</span><span class="token punctuation">(</span><span class="token keyword">const</span> ListenerCallbacks<span class="token operator">&amp;</span> callbacks<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
